import React from "react";
import {
  act,
  fireEvent,
  render,
  screen,
  waitFor,
} from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import { differenceInDays } from "date-fns";
import { composeStories } from "@storybook/react";
import { axe } from "jest-axe";
import ConsoleSpy from "../../lib/tests/ConsoleSpy";
import * as stories from "./DatePicker.stories";
import DatePicker from "./DatePicker";
import { FormControl } from "../Form";

const { Basic } = composeStories(stories) as any;

// see https://floating-ui.com/docs/react#testing
// see https://github.com/testing-library/react-testing-library/issues/1073
const waitForFloatingUI = async (cb: () => void) => {
  cb();
  await act(() => Promise.resolve());
};

describe("DatePicker component", () => {
  const consoleSpy = ConsoleSpy();

  it("pass A11Y", async () => {
    const { container } = render(<Basic />);
    const results = await axe(container);
    expect(results).toHaveNoViolations();
  });

  it("passes through props", async () => {
    const { rerender } = render(<DatePicker isOpen data-testid="datepicker" />);
    expect(screen.getByTestId("datepicker")).toBeInTheDocument();

    rerender(<DatePicker inputProps={{ "data-testid": "datepicker" }} />);
    await waitForFloatingUI(() => {});
    expect(screen.getByTestId("datepicker")).toBeInTheDocument();
  });

  it("open and close calendar correctly", async () => {
    const { container } = render(<DatePicker data-testid="calendar-test-id" />);
    const calendarBtn = screen.getByRole("button", { name: "Open calendar" });
    const input = screen.getByRole("textbox");

    // open calendar by clicking on calendar button
    // await toggleCalendar();
    await waitForFloatingUI(() => fireEvent.click(calendarBtn));
    expect(screen.getByTestId("calendar-test-id")).toBeInTheDocument();

    // close calendar by clicking again on calendar button
    await waitForFloatingUI(() => fireEvent.click(calendarBtn));
    expect(screen.queryByTestId("calendar-test-id")).toBeNull();

    // open calendar by clicking on input
    await waitForFloatingUI(() => fireEvent.click(input));
    expect(screen.getByTestId("calendar-test-id")).toBeInTheDocument();
    // click again on input does not close calendar
    fireEvent.click(input);
    expect(screen.getByTestId("calendar-test-id")).toBeInTheDocument();

    // close calendar by clicking outside
    fireEvent.mouseDown(container);
    expect(screen.queryByTestId("calendar-test-id")).toBeNull();

    // close calendar by removing focus
    fireEvent.click(input);
    expect(screen.getByTestId("calendar-test-id")).toBeInTheDocument();
    await waitForFloatingUI(() => fireEvent.blur(input));
    expect(screen.queryByTestId("calendar-test-id")).toBeNull();

    // open/close calendar with keys
    await userEvent.type(input, "{arrowdown}");
    expect(screen.getByTestId("calendar-test-id")).toBeInTheDocument();
    await userEvent.type(input, "{escape}");
    expect(screen.queryByTestId("calendar-test-id")).toBeNull();
  });

  it("allow to select a single date in calendar", async () => {
    const onChange = jest.fn();
    render(
      <DatePicker
        onChange={onChange}
        value={new Date(2020, 0, 1)}
        data-testid="calendar-test-id"
      />
    );

    // open calendar
    await waitForFloatingUI(() =>
      fireEvent.click(screen.getByRole("button", { name: "Open calendar" }))
    );
    expect(screen.getByTestId("calendar-test-id")).toBeInTheDocument();

    // select a date
    const secondMonday = screen.getAllByRole("button", { name: /Mon/ })[1];
    fireEvent.click(secondMonday);
    expect(onChange).toHaveBeenCalledTimes(1);
    expect(onChange).toHaveBeenCalledWith(new Date(2020, 0, 6));
    await waitFor(() =>
      expect(screen.queryByTestId("calendar-test-id")).toBeNull()
    );
  });

  it("allow to select a date range in calendar", async () => {
    const onChange = jest.fn();
    render(
      <DatePicker onChange={onChange} data-testid="calendar-test-id" range />
    );

    // open calendar
    await waitForFloatingUI(() =>
      fireEvent.click(
        screen.getAllByRole("button", { name: "Open calendar" })[0]
      )
    );
    expect(screen.getByTestId("calendar-test-id")).toBeInTheDocument();

    // select start date
    const secondMonday = screen.getAllByRole("button", { name: /Mon/ })[1];
    fireEvent.click(secondMonday);
    expect(onChange).toHaveBeenCalledTimes(1);
    expect(onChange.mock.calls[0][0]).toHaveLength(1);

    // select an earlier state date
    const secondSunday = screen.getAllByRole("button", { name: /Sun/ })[1];
    fireEvent.click(secondSunday);
    expect(onChange).toHaveBeenCalledTimes(2);
    expect(onChange.mock.calls[1][0]).toHaveLength(1);

    // select end date
    const thirdFriday = screen.getAllByRole("button", { name: /Fri/ })[2];
    fireEvent.click(thirdFriday);
    expect(onChange).toHaveBeenCalledTimes(3);
    const range = onChange.mock.calls[2][0];
    expect(range).toHaveLength(2);
    expect(differenceInDays(range[1], range[0])).toEqual(12);
    await waitFor(() =>
      expect(screen.queryByTestId("calendar-test-id")).toBeNull()
    );
  });

  it("allow to select a single date in calendar in range mode", async () => {
    const onChange = jest.fn();
    render(
      <DatePicker onChange={onChange} data-testid="calendar-test-id" range />
    );

    // open calendar
    await waitForFloatingUI(() =>
      fireEvent.click(
        screen.getAllByRole("button", { name: "Open calendar" })[0]
      )
    );
    expect(screen.getByTestId("calendar-test-id")).toBeInTheDocument();

    // select start date
    const secondMonday = screen.getAllByRole("button", { name: /Mon/ })[1];
    fireEvent.click(secondMonday);
    expect(onChange).toHaveBeenCalledTimes(1);
    expect(onChange.mock.calls[0][0]).toHaveLength(1);

    // select end date
    fireEvent.click(secondMonday);
    expect(onChange).toHaveBeenCalledTimes(2);
    const range = onChange.mock.calls[1][0];
    expect(range).toHaveLength(2);
    expect(differenceInDays(range[1], range[0])).toEqual(0);
    await waitFor(() =>
      expect(screen.queryByTestId("calendar-test-id")).toBeNull()
    );
  });

  it("allow to input a single date", () => {
    const onChange = jest.fn();
    render(<DatePicker onChange={onChange} />);
    fireEvent.change(screen.getByRole("textbox"), {
      target: { value: "01/01/2020" },
    });
    expect(onChange).toHaveBeenCalledTimes(1);
    expect(onChange).toHaveBeenCalledWith(new Date(2020, 0, 1));
  });

  it("allow to input a date range", async () => {
    const onChange = jest.fn();
    render(<DatePicker range onChange={onChange} />);
    const inputs = screen.getAllByRole("textbox");
    await waitForFloatingUI(() =>
      fireEvent.change(inputs[0], { target: { value: "01/01/2020" } })
    );
    expect(onChange).toHaveBeenCalledTimes(1);
    expect(onChange).toHaveBeenCalledWith([new Date(2020, 0, 1)]);
    await waitForFloatingUI(() =>
      fireEvent.change(inputs[1], { target: { value: "10/01/2020" } })
    );
    expect(onChange).toHaveBeenCalledTimes(2);
    expect(onChange).toHaveBeenCalledWith([
      new Date(2020, 0, 1),
      new Date(2020, 0, 10),
    ]);
  });

  it("does not allow selecting a date outside min/max dates", () => {
    const onChange = jest.fn();
    render(
      <DatePicker
        isOpen
        range
        minDate={new Date(2020, 0, 10)}
        maxDate={new Date(2020, 0, 20)}
        onChange={onChange}
      />
    );
    const inputs = screen.getAllByRole("textbox");
    fireEvent.change(inputs[0], { target: { value: "01/01/2020" } });
    expect(onChange).toHaveBeenCalledTimes(0);
    fireEvent.change(inputs[1], { target: { value: "25/01/2020" } });
    expect(onChange).toHaveBeenCalledTimes(0);
    const mondays = screen.getAllByRole("button", { name: /Mon/ });
    fireEvent.click(mondays[1]);
    expect(onChange).toHaveBeenCalledTimes(0);
    fireEvent.click(mondays[4]);
    expect(onChange).toHaveBeenCalledTimes(0);
  });

  it("set invalid state on input blur if needed", () => {
    const onChange = jest.fn();
    render(<DatePicker onChange={onChange} />);
    const input = screen.getByRole("textbox");
    fireEvent.change(input, { target: { value: "blablabla" } });
    fireEvent.blur(input);
    expect(onChange).toHaveBeenCalledTimes(0);
    expect(input).toHaveAttribute("aria-invalid", "true");
  });

  it("insert separators automaticallly", async () => {
    consoleSpy.log.mockRestore();
    const onChange = jest.fn();
    const { rerender } = render(<DatePicker onChange={onChange} />);
    const input = screen.getByRole("textbox");
    await userEvent.type(input, "0");
    expect(input).toHaveValue("0");
    await userEvent.type(input, "5");
    expect(input).toHaveValue("05/");
    await userEvent.type(input, "0");
    expect(input).toHaveValue("05/0");
    await userEvent.type(input, "5");
    expect(input).toHaveValue("05/05/");
    await userEvent.type(input, "20");
    expect(input).toHaveValue("05/05/20");
    await userEvent.type(input, "20");
    expect(onChange).toHaveBeenCalledTimes(1);
    expect(onChange).toHaveBeenCalledWith(new Date(2020, 4, 5));

    rerender(
      <DatePicker
        onChange={onChange}
        dateFormat="dd-mm-yyyy"
        dateSeparator="-"
      />
    );
    await userEvent.clear(input);
    await userEvent.type(input, "05");
    expect(input).toHaveValue("05-");
    await userEvent.type(input, "05");
    expect(input).toHaveValue("05-05-");
    await userEvent.type(input, "2020");
    expect(onChange).toHaveBeenCalledTimes(2);
  });

  it("manage input cursor", async () => {
    const onChange = jest.fn();
    render(<DatePicker onChange={onChange} />);
    const input: HTMLInputElement = screen.getByRole(
      "textbox"
    ) as HTMLInputElement;
    await userEvent.type(input, "05");
    expect(input).toHaveValue("05/");
    expect(input.selectionStart).toEqual(3);
    await userEvent.type(input, "0");
    expect(input).toHaveValue("05/0");
    expect(input.selectionStart).toEqual(4);
    await userEvent.type(input, "5");
    expect(input).toHaveValue("05/05/");
    expect(input.selectionStart).toEqual(6);

    // move cursor in incomplete date string
    input.setSelectionRange(1, 1);
    expect(input.selectionStart).toEqual(1);
    await userEvent.type(input, "111", {
      initialSelectionStart: 1,
      initialSelectionEnd: 1,
    });
    expect(input).toHaveValue("01/11/");
    expect(input.selectionStart).toEqual(6);
  });

  it("dispatch onchange when user input invalid date", async () => {
    const onChange = jest.fn();
    render(
      <DatePicker
        isOpen
        minDate={new Date(2020, 0, 10)}
        maxDate={new Date(2020, 0, 20)}
        onChange={onChange}
      />
    );
    const inputs = screen.getAllByRole("textbox");

    // select a valid date in calendar
    const mondays = screen.getAllByRole("button", { name: /Mon/ });
    await waitForFloatingUI(() => fireEvent.click(mondays[2]));
    expect(onChange).toHaveBeenCalledTimes(1);

    // type an invalid date
    fireEvent.change(inputs[0], { target: { value: "01/01/2020" } });
    expect(onChange).toHaveBeenCalledTimes(2);
    expect(onChange).toHaveBeenLastCalledWith(undefined);
  });

  it("allows to change single value programmatically", async () => {
    const onChange = jest.fn();
    const { rerender } = render(
      <DatePicker isOpen onChange={onChange} value={new Date(2020, 0, 10)} />
    );
    await waitForFloatingUI(() => {});
    const inputs = screen.getAllByRole("textbox");
    expect(inputs[0]).toHaveValue("10/01/2020");

    rerender(<DatePicker isOpen onChange={onChange} value={null} />);
    expect(inputs[0]).toHaveValue("");

    rerender(
      <DatePicker isOpen onChange={onChange} value={new Date(2022, 0, 15)} />
    );
    expect(inputs[0]).toHaveValue("15/01/2022");
  });

  it("allows to change multiple value programmatically", async () => {
    const onChange = jest.fn();
    const { rerender } = render(
      <DatePicker
        isOpen
        range
        onChange={onChange}
        value={[new Date(2020, 0, 10), new Date(2020, 0, 20)]}
      />
    );
    await waitForFloatingUI(() => {});
    const inputs = screen.getAllByRole("textbox");
    expect(inputs[0]).toHaveValue("10/01/2020");
    expect(inputs[1]).toHaveValue("20/01/2020");

    rerender(<DatePicker range isOpen onChange={onChange} value={null} />);
    expect(inputs[0]).toHaveValue("");
    expect(inputs[1]).toHaveValue("");

    rerender(
      <DatePicker
        isOpen
        range
        onChange={onChange}
        value={[new Date(2020, 0, 5), new Date(2020, 0, 15)]}
      />
    );
    expect(inputs[0]).toHaveValue("05/01/2020");
    expect(inputs[1]).toHaveValue("15/01/2020");
  });

  it("reset valid/invalid status on clear #1172", () => {
    const onChange = jest.fn();
    render(<DatePicker showClearButton onChange={onChange} />);

    const input = screen.getByRole("textbox");
    fireEvent.change(input, { target: { value: "0101" } });
    fireEvent.blur(input);
    expect(onChange).toHaveBeenCalledTimes(0);
    expect(input).toHaveAttribute("aria-invalid", "true");

    fireEvent.click(screen.getByRole("button", { name: "Clear date" }));
    expect(input).not.toHaveAttribute("aria-invalid");
  });

  it("updating date string from any cursor position #1172", async () => {
    const onChange = jest.fn();
    render(<DatePicker onChange={onChange} />);

    const input: HTMLInputElement = screen.getByRole(
      "textbox"
    ) as HTMLInputElement;
    await userEvent.type(input, "01012020");
    expect(input).toHaveValue("01/01/2020");
    expect(input.selectionStart).toEqual(10);

    input.setSelectionRange(0, 0);
    await userEvent.type(input, "0505", {
      initialSelectionStart: 0,
      initialSelectionEnd: 0,
    });
    expect(input.selectionStart).toEqual(6);
    expect(input).toHaveValue("05/05/");

    input.setSelectionRange(2, 2);
    await userEvent.type(input, "1", {
      initialSelectionStart: 2,
      initialSelectionEnd: 2,
    });
    expect(input.selectionStart).toEqual(4);
    expect(input).toHaveValue("05/1");
  });

  it("handle custom locale/dateFormat/datePattern/dateSeparator combination", async () => {
    const onChange = jest.fn();
    render(
      <DatePicker
        onChange={onChange}
        locale="fr-FR"
        dateFormat="jj-mm-aaaa"
        datePattern="[0-9]{2}-[0-9]{2}-[0-9]{4}"
        dateSeparator="-"
      />
    );
    const input: HTMLInputElement = screen.getByRole(
      "textbox"
    ) as HTMLInputElement;
    await userEvent.type(input, "05");
    expect(input).toHaveValue("05-");
    expect(input.selectionStart).toEqual(3);
    await userEvent.type(input, "0");
    expect(input).toHaveValue("05-0");
    expect(input.selectionStart).toEqual(4);
    await userEvent.type(input, "5");
    expect(input).toHaveValue("05-05-");
    expect(input.selectionStart).toEqual(6);

    // move cursor in incomplete date string
    input.setSelectionRange(1, 1);
    expect(input.selectionStart).toEqual(1);
    await userEvent.type(input, "111", {
      initialSelectionStart: 1,
      initialSelectionEnd: 1,
    });
    expect(input).toHaveValue("01-11-");
    expect(input.selectionStart).toEqual(6);

    // complete date input
    await userEvent.type(input, "2020");
    expect(input).toHaveValue("01-11-2020");
    expect(onChange).toHaveBeenCalledTimes(1);
    expect(onChange).toHaveBeenLastCalledWith(new Date(2020, 10, 1));
  });

  it("handle german date input #2342", async () => {
    consoleSpy.log.mockRestore();

    const onChange = jest.fn();
    render(
      <DatePicker
        onChange={onChange}
        locale="de-DE"
        dateFormat="DD.MM.YYYY"
        datePattern="[0-9]{2}.[0-9]{2}.[0-9]{4}"
        dateSeparator="."
      />
    );
    const input: HTMLInputElement = screen.getByRole(
      "textbox"
    ) as HTMLInputElement;
    await userEvent.type(input, "05");
    expect(input).toHaveValue("05.");
    expect(input.selectionStart).toEqual(3);
    await userEvent.type(input, "0");
    expect(input).toHaveValue("05.0");
    expect(input.selectionStart).toEqual(4);
    await userEvent.type(input, "5");
    expect(input).toHaveValue("05.05.");
    expect(input.selectionStart).toEqual(6);

    // move cursor in incomplete date string
    input.setSelectionRange(1, 1);
    expect(input.selectionStart).toEqual(1);
    await userEvent.type(input, "111", {
      initialSelectionStart: 1,
      initialSelectionEnd: 1,
    });
    expect(input).toHaveValue("01.11.");
    expect(input.selectionStart).toEqual(6);

    // complete date input
    await userEvent.type(input, "2020");
    expect(input).toHaveValue("01.11.2020");
    expect(onChange).toHaveBeenCalledTimes(1);
    expect(onChange).toHaveBeenLastCalledWith(new Date(2020, 10, 1));
  });

  it("allows customized date formats through callback props", async () => {
    const datePattern = "[0-9]{2}-[a-zA-Z]{3}-[0-9]{4}";
    const intl = new Intl.DateTimeFormat("en-US", { month: "short" });
    // custom date to string formatter function
    const formatDateToString = (
      date: Date,
      separator: string,
      locale: string
    ) => {
      // format month as short string representation through Intl API
      const parts = intl.formatToParts(date);
      const monthPart = parts.find((part) => part.type === "month");
      if (!monthPart) return "";
      // format day on two letters
      let day = `${date.getDate()}`;
      if (day.length === 1) day = `0${day}`;
      return `${day}${separator}${
        monthPart.value
      }${separator}${date.getFullYear()}`;
    };
    // custom string to date formatter function
    const formatStringToDate = (
      inputValue: string,
      separator: string,
      locale: string
    ) => {
      return new Date(inputValue);
    };

    const onChange = jest.fn();
    const onValidation = jest.fn();
    render(
      <DatePicker
        dateFormat="dd-MMM-yyyy"
        datePattern={datePattern}
        dateSeparator="-"
        formatDateToString={formatDateToString}
        formatStringToDate={formatStringToDate}
        locale="en-US"
        onChange={onChange}
        onValidation={onValidation}
      />
    );
    const input: HTMLInputElement = screen.getByRole(
      "textbox"
    ) as HTMLInputElement;

    // input bad format date
    await userEvent.type(input, "aaaaaaaaa");
    expect(input).toHaveValue("aa-aaa-aaaa");
    fireEvent.blur(input);
    expect(onChange).toHaveBeenCalledTimes(0);
    expect(onValidation).toHaveBeenCalledTimes(1);
    expect(onValidation).toHaveBeenLastCalledWith(false);

    // input good format date
    await userEvent.clear(input);
    expect(onChange).toHaveBeenCalledTimes(1);
    expect(onValidation).toHaveBeenCalledTimes(2);
    expect(onValidation).toHaveBeenLastCalledWith(true);
    await userEvent.type(input, "01-dec-2000");
    expect(input).toHaveValue("01-Dec-2000");
    expect(onChange).toHaveBeenCalledTimes(2);
    expect(onChange).toHaveBeenLastCalledWith(new Date(2000, 11, 1));
    expect(onValidation).toHaveBeenCalledTimes(3);
    expect(onValidation).toHaveBeenLastCalledWith(true);
  });

  it("allows state to be set from formcontrol", async () => {
    // render with error
    const { rerender } = render(
      <FormControl error errorText="error_from_formcontrol">
        <DatePicker />
      </FormControl>
    );
    const input = screen.getByRole("textbox");
    expect(input).toHaveAttribute("aria-invalid", "true");
    expect(screen.getByText("error_from_formcontrol")).toBeDefined();

    // render without error
    rerender(
      <FormControl>
        <DatePicker />
      </FormControl>
    );
    expect(input).not.toHaveAttribute("aria-invalid");
    expect(screen.queryByText("error_from_formcontrol")).toBeNull();

    // render with success
    rerender(
      <FormControl success successText="success_from_formcontrol">
        <DatePicker />
      </FormControl>
    );
    expect(input).not.toHaveAttribute("aria-invalid");
    expect(screen.getByText("success_from_formcontrol")).toBeDefined();
  });

  it("do not allow input of dates outside min/max range", async () => {
    consoleSpy.log.mockRestore();
    const onChange = jest.fn();
    render(
      <DatePicker
        onChange={onChange}
        minDate={new Date(2019, 1, 1)}
        maxDate={new Date(2021, 10, 30)}
      />
    );
    const input = screen.getByRole("textbox");

    // input date before min
    fireEvent.change(input, { target: { value: "01/01/2000" } });
    expect(onChange).toHaveBeenCalledTimes(1);
    expect(onChange).toHaveBeenLastCalledWith(undefined);

    // input date in range
    fireEvent.change(input, { target: { value: "01/01/2020" } });
    expect(onChange).toHaveBeenCalledTimes(2);
    expect(onChange).toHaveBeenLastCalledWith(new Date(2020, 0, 1));

    // clear input
    await userEvent.clear(input);
    expect(onChange).toHaveBeenCalledTimes(3);

    // input date after max
    fireEvent.change(input, { target: { value: "01/01/2022" } });
    expect(onChange).toHaveBeenCalledTimes(4);
    expect(onChange).toHaveBeenLastCalledWith(undefined);
  });

  it("reset date range when choosing a new date in calendar #2006", async () => {
    const onChange = jest.fn();
    render(
      <DatePicker
        onChange={onChange}
        data-testid="calendar-test-id"
        range
        value={[new Date(2000, 0, 1), new Date(2000, 0, 10)]}
      />
    );

    // open calendar
    await waitForFloatingUI(() =>
      fireEvent.click(
        screen.getAllByRole("button", { name: "Open calendar" })[0]
      )
    );

    // change start date
    const secondMonday = screen.getAllByRole("button", { name: /Mon/ })[1];
    fireEvent.click(secondMonday);

    // trigger onChange with single date
    expect(onChange).toHaveBeenCalledTimes(1);
    expect(onChange).toHaveBeenLastCalledWith([new Date(2000, 0, 3)]);

    // end input should be cleared
    const inputs = screen.getAllByRole("textbox");
    expect(inputs[1]).toHaveValue("");
  });
});
